import math

def lcm_all(nums):
    """Least common multiple of a list of positive integers."""
    if not nums:
        return 1

    def lcm(a, b):
        return (a * b) // math.gcd(a, b)

    result = nums[0]
    for n in nums[1:]:
        result = lcm(result, n)
    return result
```

