import unittest
from unittest import mock
import profile


class TestProfileDisplayName(unittest.TestCase):
    """Tests for profile.display_name to ensure deleted users return 'Guest'."""

    @mock.patch('profile.store')
    def test_existing_user_returns_name(self, mock_store):
        """For a known user, return the actual name."""
        mock_store.get_user.return_value = {"name": "Alice"}
        result = profile.display_name(1)
        assert result == "Alice"

    @mock.patch('profile.store')
    def test_deleted_user_returns_guest(self, mock_store):
        """For a deleted/unknown user (KeyError), return 'Guest'."""
        mock_store.get_user.side_effect = KeyError("User not found")
        result = profile.display_name(999)
        assert result == "Guest"

    @mock.patch('profile.store')
    def test_deleted_user_with_none_name_returns_guest(self, mock_store):
        """If get_user returns a dict with None name, still return 'Guest'? 
        Actually, the requirement says KeyError causes 'Guest'. 
        If the key exists but name is missing, KeyError on ["name"] triggers."""
        mock_store.get_user.return_value = {"id": 999}
        result = profile.display_name(999)
        assert result == "Guest"

    @mock.patch('profile.store')
    def test_deleted_user_with_empty_dict_returns_guest(self, mock_store):
        """Empty dict from get_user means no 'name' key -> KeyError -> 'Guest'."""
        mock_store.get_user.return_value = {}
        result = profile.display_name(0)
        assert result == "Guest"

    @mock.patch('profile.store')
    def test_deleted_user_raises_other_exception_still_crashes_or_handles(self, mock_store):
        """If store raises something other than KeyError, it should propagate.
        The fix should only catch KeyError, not all exceptions."""
        mock_store.get_user.side_effect = RuntimeError("Connection lost")
        try:
            profile.display_name(-1)
            assert False, "Expected RuntimeError to propagate"
        except RuntimeError:
            pass  # Expected

    @mock.patch('profile.store')
    def test_deleted_user_with_missing_name_key_returns_guest(self, mock_store):
        """User exists but has no 'name' field -> KeyError on access -> 'Guest'."""
        mock_store.get_user.return_value = {"email": "test@example.com"}
        result = profile.display_name(42)
        assert result == "Guest"

    @mock.patch('profile.store')
    def test_existing_user_with_name_returns_correct_name(self, mock_store):
        """Ensure that valid users with names are returned correctly."""
        mock_store.get_user.return_value = {"name": "Bob", "id": 2}
        result = profile.display_name(2)
        assert result == "Bob"

    @mock.patch('profile.store')
    def test_deleted_user_keyerror_with_message_returns_guest(self, mock_store):
        """KeyError with a specific message should still result in 'Guest'."""
        mock_store.get_user.side_effect = KeyError("user_id=5 not in database")
        result = profile.display_name(5)
        assert result == "Guest"

