import plugins
import registry


# Mock the registry to simulate registered plugins
_original_lookup = registry.lookup


def _mock_lookup(name):
    """Return a mock function for the given plugin name, or None if not found."""
    if name == 'Resize':
        def mock_resize(*args):
            return f"resized {args}"
        return mock_resize
    elif name == 'resize':
        def mock_resize_lower(*args):
            return f"resized lower {args}"
        return mock_resize_lower
    elif name == 'Empty':
        def mock_empty(*args):
            return []
        return mock_empty
    return None


registry.lookup = _mock_lookup


def test_run_resize_uppercase():
    """Test running plugin 'Resize' with uppercase name."""
    result = plugins.run('Resize', 'image.png')
    assert result == "resized image.png"


def test_run_resize_lowercase():
    """Test running plugin 'resize' with lowercase name (case-insensitive)."""
    result = plugins.run('resize', 'image.png')
    assert result == "resized lower image.png"


def test_run_resize_mixed_case():
    """Test running plugin with mixed case 'rEsIzE'."""
    result = plugins.run('rEsIzE', 'image.png')
    assert result == "resized lower image.png"


def test_run_unknown_plugin():
    """Test running an unknown plugin raises KeyError."""
    try:
        plugins.run('UnknownPlugin', 'arg')
        assert False, "KeyError should have been raised"
    except KeyError as e:
        assert "no plugin" in str(e)


def test_run_empty_plugin():
    """Test running plugin 'Empty' which returns an empty list."""
    result = plugins.run('Empty')
    assert result == []


def test_run_with_multiple_args():
    """Test running plugin with multiple arguments."""
    result = plugins.run('Resize', 'a', 'b', 'c')
    assert result == "resized ('a', 'b', 'c')"


def test_run_nonexistent_plugin():
    """Test running a plugin that doesn't exist in the mock registry."""
    try:
        plugins.run('NonExistent', 'arg')
        assert False, "KeyError should have been raised"
    except KeyError as e:
        assert "no plugin" in str(e)


def test_run_resize_with_no_args():
    """Test running plugin 'Resize' with no additional arguments."""
    result = plugins.run('Resize')
    assert result == "resized ()"

