    """A single USD item should return the correct total."""
    result = basket.basket_total([5.0], "USD")
    assert result == "5.00 USD"


def test_usd_multiple_items():
    """Multiple USD items should sum correctly."""
    result = basket.basket_total([5.0, 5.0], "USD")
    assert result == "10.00 USD"


def test_usd_mixed_values():
    """Mixed USD values should sum correctly."""
    result = basket.basket_total([1.5, 2.5, 3.0], "USD")
    assert result == "7.00 USD"


def test_empty_basket_usd():
    """An empty basket in USD should return zero."""
    result = basket.basket_total([], "USD")
    assert result == "0.00 USD"


