def parse_version(text):
    """'1.2.3' -> (1, 2, 3)"""
    if text is None or not isinstance(text, str):
        return None
    text = text.strip()
    if not text:
        return None
    if text.startswith('v'):
        text = text[1:]
    text = text.strip()
    if not text:
        return None
    parts = text.split(".")
    if len(parts) != 3:
        return None
    result = []
    for p in parts:
        try:
            val = int(p)
            result.append(val)
        except ValueError:
            return None
    return tuple(result)
