from lib.privacy import mask_local


def mask_email(email):
    """Hide most of an email address for display."""
    if '@' in email:
        local, domain = email.split('@', 1)
        masked_local = mask_local(local)
        return masked_local + '@' + domain
    else:
        return mask_local(email)
